mkdir -p /tmp/p12-check && cat > /tmp/p12-check/bfs.mjs <<'EOF'
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = await load(process.argv[2]);
const air = (x, y, z) => ["minecraft:air", "minecraft:cave_air"].includes(g.blockAt(x, y, z));
const ok = (x, z) => x >= 2 && x <= 13 && z >= 26 && z <= 29 && air(x, 5, z) && air(x, 6, z) && !air(x, 4, z) ;
const cells = [];
for (let x = 2; x <= 13; x++) for (let z = 26; z <= 29; z++) if (ok(x, z)) cells.push([x, z]);
const seen = new Set(["7,26"]); const q = [[7, 26]];
while (q.length) { const [x, z] = q.shift(); for (const [dx, dz] of [[1,0],[-1,0],[0,1],[0,-1]]) { const nx = x + dx, nz = z + dz; const k = `${nx},${nz}`; if (!seen.has(k) && ok(nx, nz)) { seen.add(k); q.push([nx, nz]); } } }
console.log("standable", cells.length, "reached from dining door", cells.filter(([x, z]) => seen.has(`${x},${z}`)).length);
console.log("unreached", cells.filter(([x, z]) => !seen.has(`${x},${z}`)).map(([x, z]) => `${x},${z}`).join(" "));
console.log("hall door (12,26) reached", seen.has("12,26"), "deck (7,29) reached", seen.has("7,29"));
EOF
cd /tmp/p12-check && node bfs.mjs /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/sfvictorian-opus/crew/part-12/build.nbt 2>&1 | head -10

